import { host } from "host";

const status = await host.server.status();
const loc = status.demoLocation;
const blockX = Math.floor(loc.x) + 2;
const blockY = Math.floor(loc.y) + 2;
const blockZ = Math.floor(loc.z) + 2;

const [weatherResult, zombie1Result, zombie2Result, blockResult, broadcastResult] = await Promise.all([
  host.world.setWeather("THUNDER"),
  host.world.spawnEntity({ type: "ZOMBIE", x: Math.floor(loc.x) + 1, y: Math.floor(loc.y), z: Math.floor(loc.z) }),
  host.world.spawnEntity({ type: "ZOMBIE", x: Math.floor(loc.x) - 1, y: Math.floor(loc.y), z: Math.floor(loc.z) }),
  host.world.setBlock({ x: blockX, y: blockY, z: blockZ, type: "DIAMOND_ORE" }),
  host.chat.broadcast("A storm gathers, zombies emerge, and diamond ore has appeared at the demo site!")
]);

console.log(JSON.stringify({
  status,
  results: {
    weather: weatherResult,
    zombies: [zombie1Result, zombie2Result],
    block: blockResult,
    broadcast: broadcastResult
  }
}));

