import { host } from "host";
import config from "../config.json" with { type: "json" };

export async function broadcastSummary(): Promise<void> {
  let total = 0;
  for (const score of config.scores) {
    total += score;
  }
  const average = total / config.scores.length;
  const summary = `[${config.title}] Total: ${total}, Avg: ${average.toFixed(1)}, Samples: ${config.scores.length}`;
  await host.chat.broadcast(summary);
}
